/// Null means this serial is not a catalogued multi-disc title.
pub fn lookup(serial: []const u8) ?Entry {
    for (entries) |entry| {
        if (std.ascii.eqlIgnoreCase(entry.serial, serial)) return entry;
    }
    return null;
}
